	@Test
	void coreDatatypeIsEncodedInNonInlineLiteralIdAndSurvivesReopen(@TempDir File directory) throws Exception {
		StoreProperties properties = coreV1Properties(directory);
		LmdbStoreConfig config = nonInliningConfig();
		Literal literal = SimpleValueFactory.getInstance()
				.createLiteral("a deliberately non-inline string",
						CoreDatatype.XSD.STRING.getIri());

		long id;
		ValueStore values = new ValueStore(new File(directory, "values"), properties, config);
		try {
			id = store(values, literal);
			assertThat(ValueIds.getIdType(id)).isNotEqualTo(ValueIds.T_LITERAL);
			assertThat(ValueIds.isReference(id)).isTrue();
			assertThat(values.getValue(id)).isEqualTo(literal);
		} finally {
			values.close();
		}

		StoreProperties reopenedProperties = new StoreProperties(directory);
		assertThat(reopenedProperties.load()).isTrue();
		ValueStore reopened = new ValueStore(new File(directory, "values"), reopenedProperties, config);
		try {
			assertThat(reopened.getId(literal)).isEqualTo(id);
			assertThat(reopened.getValue(id)).isEqualTo(literal);
		} finally {
			reopened.close();
		}
	}

