	@Test
	void everyCoreDatatypeHasAStableRoundTrippingTag() {
		List<CoreDatatype> datatypes = new ArrayList<>();
		datatypes.addAll(Arrays.asList(CoreDatatype.XSD.values()));
		datatypes.addAll(Arrays.asList(CoreDatatype.RDF.values()));
		datatypes.addAll(Arrays.asList(CoreDatatype.GEO.values()));
		Set<Integer> tags = new HashSet<>();
		long ordinal = 987_654_321L;
		for (CoreDatatype datatype : datatypes) {
			int tag = ValueIds.coreDatatypeTag(datatype);
			long id = ValueIds.createCoreLiteralReferenceId(ordinal, datatype);
			assertThat(tag).isBetween(1, 63);
			assertThat(tags.add(tag)).as("unique persisted tag for %s", datatype).isTrue();
			assertThat(ValueIds.getIdType(id)).isEqualTo(ValueIds.T_CORE_LITERAL);
			assertThat(ValueIds.referenceOrdinal(id)).isEqualTo(ordinal);
			assertThat(ValueIds.coreDatatypeOfCoreLiteral(id)).isSameAs(datatype);
			assertThat(ValueIds.isReference(id)).isTrue();
			assertThat(ValueIds.isInlined(id)).isFalse();
		}
		assertThat(tags).hasSize(53);
		assertThat(ValueIds.createCoreLiteralReferenceId(ValueIds.MAX_CORE_LITERAL_REFERENCE_ORDINAL + 1,
				CoreDatatype.XSD.STRING)).isZero();
		assertThat(ValueIds.createCoreLiteralReferenceId(1, CoreDatatype.NONE)).isZero();
		assertThat(IdCapability.IDENTITY_SAFE
				.test(ValueIds.createCoreLiteralReferenceId(1, CoreDatatype.XSD.INTEGER))).isFalse();
	}

	@Test
	void batchedAndFreshWritersUseTheSameEncoding(@TempDir File directory) throws Exception {
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		Value[] input = {
				factory.createLiteral("P1D", CoreDatatype.XSD.DURATION.getIri()),
				factory.createLiteral("<p>html</p>", CoreDatatype.RDF.HTML.getIri()),
				factory.createLiteral("POINT(1 2)", CoreDatatype.GEO.WKT_LITERAL.getIri()),
				factory.createLiteral("custom", factory.createIRI("urn:test:custom"))
		};

		File batchDirectory = new File(directory, "batch");
		ValueStore batch = new ValueStore(new File(batchDirectory, "values"), coreV1Properties(batchDirectory),
				nonInliningConfig());
		long[] batchIds = new long[input.length];
		try {
			batch.startTransaction(true);
			batch.storeValues(input, batchIds, input.length);
			batch.commit();
			assertEncodedKindsAndValues(batch, input, batchIds);
		} finally {
			batch.close();
		}

		File freshDirectory = new File(directory, "fresh");
		ValueStore fresh = new ValueStore(new File(freshDirectory, "values"), coreV1Properties(freshDirectory),
				nonInliningConfig());
		try {
			fresh.startTransaction(true);
			ValueStore.FreshValueSession session = fresh.startFreshValueSessionIfEmpty();
			ValueStore.PreparedValueBatch prepared = fresh.prepareFreshValues(session, input);
			long[] freshIds = prepared.ids().clone();
			fresh.persistPreparedValues(prepared);
			fresh.commit();
			fresh.commitFreshValueTransaction(session);
			fresh.publishPreparedValues(prepared);
			assertEncodedKindsAndValues(fresh, input, freshIds);
		} finally {
			fresh.close();
		}
	}

	@Test
	void queryTypeTestsRecognizeEncodedReferences(@TempDir File directory) {
		LmdbStore sail = new LmdbStore(directory, nonInliningConfig());
		SailRepository repository = new SailRepository(sail);
		repository.init();
		try (var connection = repository.getConnection()) {
			SimpleValueFactory factory = SimpleValueFactory.getInstance();
			IRI subject = factory.createIRI("urn:test:subject");
			IRI predicate = factory.createIRI("urn:test:predicate");
			connection.add(subject, predicate, factory.createLiteral("007", XSD.INTEGER));
			connection.add(subject, predicate, factory.createLiteral("text", XSD.STRING));
			connection.add(subject, predicate, factory.createLiteral("<p>html</p>", RDF.HTML));
			connection.add(subject, predicate,
					factory.createLiteral("custom", factory.createIRI("urn:test:datatype")));

			try (var results = connection.prepareTupleQuery("SELECT (COUNT(?o) AS ?literals) "
					+ "WHERE { ?s ?p ?o FILTER(isLiteral(?o)) }").evaluate()) {
				BindingSet result = results.next();
				assertThat(((Literal) result.getValue("literals")).longValue()).isEqualTo(4L);
			}
			try (var results = connection.prepareTupleQuery("SELECT (COUNT(?o) AS ?numeric) "
					+ "WHERE { ?s ?p ?o FILTER(isNumeric(?o)) }").evaluate()) {
				BindingSet result = results.next();
				assertThat(((Literal) result.getValue("numeric")).longValue()).isEqualTo(1L);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertEncodedKindsAndValues(ValueStore store, Value[] values, long[] ids) throws Exception {
		for (int i = 0; i < values.length; i++) {
			int expectedType = i == values.length - 1 ? ValueIds.T_LITERAL : ValueIds.T_CORE_LITERAL;
			assertThat(ValueIds.getIdType(ids[i])).isEqualTo(expectedType);
			assertThat(store.getValue(ids[i])).isEqualTo(values[i]);
		}
	}

	private static StoreProperties coreV1Properties(File directory) throws Exception {
		return persistedProperties(directory, "4", CORE_V1);
	}

	private static StoreProperties persistedProperties(File directory, String version, String literalEncoding)
			throws Exception {
		Files.createDirectories(directory.toPath());
		Properties raw = new Properties();
		raw.setProperty(StoreProperties.VERSION_KEY, version);
		raw.setProperty(StoreProperties.INDEXES_KEY, "spoc,posc");
		raw.setProperty(StoreProperties.TRIPLE_TERM_INDEXES_KEY, "spoc");
		raw.setProperty(StoreProperties.INLINE_LITERALS_KEY, "false");
		if (literalEncoding != null) {
			raw.setProperty(ENCODING_KEY, literalEncoding);
		}
		try (var output = Files.newOutputStream(new File(directory, StoreProperties.FILE_NAME).toPath())) {
			raw.store(output, "test");
		}
		StoreProperties properties = new StoreProperties(directory);
		assertThat(properties.load()).isTrue();
		return properties;
	}

	private static LmdbStoreConfig nonInliningConfig() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false);
	}

	private static long store(ValueStore values, Literal literal) throws Exception {
		values.startTransaction(true);
		long id = values.storeValue(literal);
		values.commit();
		return id;
	}
